// ── SWAP-POINT 2 of 3: PREP ─────────────────────────────────────────────────
// Shape each closed-won deal's facts into prompt context. No scoring here — the
// local LLM does the drafting. To clone this agent for another RevOps function,
// change three things only: the SQL (FETCH above), THIS prep block, and the
// LLM PROMPT below.
return $input.all().map(item => {
  const o = item.json;
  const facts = {
    opp_id:    o.id,
    deal:      o.name,
    account:   o.account,
    owner_rep: o.owner_rep,
    amount:    o.amount,
    close_date: o.close_date,
    champion:  o.champion_identified ? 'identified' : 'none identified',
    competitor: o.competitor || 'none noted',
    next_step: o.next_step || 'none recorded'
  };

  // ── SWAP-POINT 3 of 3: PROMPT ─────────────────────────────────────────────
  const prompt = [
    'You are a RevOps handoff orchestrator. A deal just closed WON.',
    'Draft the sales -> Customer Success handoff for ONE deal.',
    'Respond with STRICT JSON ONLY, no prose, exactly:',
    '{"brief": string, "tasks": [{"owner": "CS"|"Onboarding"|"AE", "task": string}], "watch_outs": [string]}',
    '- brief: 3-4 sentences: who bought, what/why, key contacts, commercial context.',
    '- tasks: the onboarding checklist, each with an owner (CS, Onboarding, or AE).',
    '- watch_outs: risks, promises made, or competitor context CS must honor.',
    'Use ONLY the deal facts below. Do NOT invent contract terms, dates, or names not given.',
    '',
    `Deal: ${facts.deal} | Account: ${facts.account} | Owner (AE): ${facts.owner_rep}`,
    `Amount: ${facts.amount} | Close date: ${facts.close_date}`,
    `Champion: ${facts.champion} | Competitor displaced: ${facts.competitor}`,
    `Promised next step / notes: ${facts.next_step}`
  ].join('\n');

  return { json: { ...facts, prompt } };
});

// Parse the local LLM's JSON handoff. On ANY failure, synthesize a templated brief
// + a default onboarding checklist from the deal facts — so a run NEVER breaks.
const f = $('Shape Deal Facts').item.json;
let brief, tasks, watch_outs, source;

const defaultTasks = [
  { owner: 'CS',         task: `Schedule kickoff call with ${f.account}` },
  { owner: 'Onboarding', task: 'Provision the account and set up access' },
  { owner: 'CS',         task: 'Build a 30/60/90 success plan' },
  { owner: 'AE',         task: 'Introduce the CS owner and hand over deal context' }
];

try {
  // Ollama /api/generate returns model text in `response`; native chat uses message.content.
  const raw = ($json.response ?? ($json.message && $json.message.content) ?? '').trim();
  const parsed = JSON.parse(raw);
  brief = String(parsed.brief || '').trim();
  tasks = Array.isArray(parsed.tasks)
    ? parsed.tasks
        .map(t => ({ owner: String(t.owner || 'CS').trim(), task: String(t.task || '').trim() }))
        .filter(t => t.task)
    : [];
  watch_outs = Array.isArray(parsed.watch_outs)
    ? parsed.watch_outs.map(w => String(w).trim()).filter(Boolean)
    : [];
  if (!brief || tasks.length === 0) throw new Error('missing brief or tasks');
  source = 'llm';
} catch (e) {
  const champLine = f.champion === 'identified'
    ? 'A champion was identified on the account.'
    : 'No champion was identified - CS should establish one early.';
  const compLine = f.competitor !== 'none noted' ? ` Displaced ${f.competitor}.` : '';
  brief = `${f.account} closed won for $${f.amount} (AE: ${f.owner_rep}). ${champLine}${compLine} Notes on file: ${f.next_step}.`;
  tasks = defaultTasks;
  watch_outs = [];
  if (f.competitor !== 'none noted') watch_outs.push(`Competitor context to honor: displaced ${f.competitor}.`);
  if (f.next_step !== 'none recorded') watch_outs.push(`Promise made in the sale: ${f.next_step}.`);
  if (f.champion !== 'identified')    watch_outs.push('No champion identified - mitigate single-threading risk.');
  source = 'fallback';
}

const watch_outs_text = watch_outs.length ? watch_outs.join('; ') : 'None';
const tasks_text = tasks.map(t => `  - [${t.owner}] ${t.task}`).join('\n');

return { json: {
  opp_id: f.opp_id, account: f.account, amount: f.amount, owner_rep: f.owner_rep, deal: f.deal,
  brief, tasks, tasks_text, watch_outs, watch_outs_text, reason_source: source
} };
